import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import CourseList from '../components/courses/CourseList';
import CourseFilter from '../components/courses/CourseFilter';
import CourseSearch from '../components/courses/CourseSearch';
import { useCourses, useCoursesByCategory, useCoursesByLevel, useSearchCourses } from '../hooks/useCourses';

const Courses: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [selectedCategory, setSelectedCategory] = useState(searchParams.get('category') || 'all');
  const [selectedLevel, setSelectedLevel] = useState(searchParams.get('level') || 'all');
  const [selectedSort, setSelectedSort] = useState(searchParams.get('sort') || 'rating');
  const [searchQuery, setSearchQuery] = useState(searchParams.get('search') || '');

  // Fetch courses based on filters
  const { data: allCourses, isLoading: isLoadingAll } = useCourses();
  const { data: categoryCourses, isLoading: isLoadingCategory } = useCoursesByCategory(selectedCategory);
  const { data: levelCourses, isLoading: isLoadingLevel } = useCoursesByLevel(selectedLevel);
  const { data: searchResults, isLoading: isLoadingSearch } = useSearchCourses(searchQuery);

  // Update URL when filters change
  useEffect(() => {
    const params = new URLSearchParams();
    if (selectedCategory !== 'all') params.set('category', selectedCategory);
    if (selectedLevel !== 'all') params.set('level', selectedLevel);
    if (selectedSort !== 'rating') params.set('sort', selectedSort);
    if (searchQuery) params.set('search', searchQuery);
    setSearchParams(params);
  }, [selectedCategory, selectedLevel, selectedSort, searchQuery, setSearchParams]);

  // Get the appropriate courses based on filters
  const getFilteredCourses = () => {
    let courses = allCourses || [];
    
    if (searchQuery) {
      courses = searchResults || [];
    } else if (selectedCategory !== 'all') {
      courses = categoryCourses || [];
    } else if (selectedLevel !== 'all') {
      courses = levelCourses || [];
    }

    // Apply sorting
    return [...courses].sort((a, b) => {
      switch (selectedSort) {
        case 'rating':
          return b.rating - a.rating;
        case 'students':
          return b.students - a.students;
        case 'price-asc':
          return a.price - b.price;
        case 'price-desc':
          return b.price - a.price;
        default:
          return 0;
      }
    });
  };

  const isLoading = isLoadingAll || isLoadingCategory || isLoadingLevel || isLoadingSearch;
  const courses = getFilteredCourses();

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-8">Available Courses</h1>
      
      <CourseSearch
        onSearch={setSearchQuery}
        initialQuery={searchQuery}
      />

      <CourseFilter
        selectedCategory={selectedCategory}
        selectedLevel={selectedLevel}
        selectedSort={selectedSort}
        onCategoryChange={setSelectedCategory}
        onLevelChange={setSelectedLevel}
        onSortChange={setSelectedSort}
      />

      <CourseList
        courses={courses}
        isLoading={isLoading}
      />
    </div>
  );
};

export default Courses; 