import React from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useUserCourses } from '../hooks/useCourses';
import { Link } from 'react-router-dom';

interface Course {
  id: string;
  title: string;
  progress: number;
}

const Dashboard: React.FC = () => {
  const { user } = useAuth();
  const { data: userCourses, isLoading, error } = useUserCourses();

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  // Fix array property errors by ensuring userCourses is always an array and has correct type
  const courses: Course[] = Array.isArray(userCourses) ? userCourses : [];
  const inProgressCourses = courses.filter((course) => course.progress > 0 && course.progress < 100);
  const completedCourses = courses.filter((course) => course.progress === 100);
  const notStartedCourses = courses.filter((course) => course.progress === 0);
  const totalProgress = courses.length ? courses.reduce((acc, course) => acc + course.progress, 0) / courses.length : 0;

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h1 className="text-2xl font-bold text-gray-800 mb-4">Welcome back, {user?.name}!</h1>
          <p className="text-gray-600">Continue your learning journey from where you left off.</p>
        </div>

        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-6">Learning Progress</h2>
          
          <div className="mb-8">
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-medium text-gray-700">Overall Progress</span>
              <span className="text-sm font-medium text-gray-700">{Math.round(totalProgress)}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5">
              <div
                className="bg-blue-500 h-2.5 rounded-full"
                style={{ width: `${totalProgress}%` }}
              ></div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-gray-50 rounded-lg p-4">
              <h3 className="text-lg font-medium text-gray-800 mb-2">In Progress</h3>
              <p className="text-3xl font-bold text-blue-500">{inProgressCourses.length}</p>
            </div>
            <div className="bg-gray-50 rounded-lg p-4">
              <h3 className="text-lg font-medium text-gray-800 mb-2">Completed</h3>
              <p className="text-3xl font-bold text-green-500">{completedCourses.length}</p>
            </div>
            <div className="bg-gray-50 rounded-lg p-4">
              <h3 className="text-lg font-medium text-gray-800 mb-2">Not Started</h3>
              <p className="text-3xl font-bold text-gray-500">{notStartedCourses.length}</p>
            </div>
          </div>
        </div>

        {inProgressCourses.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-2xl font-bold text-gray-800 mb-6">Continue Learning</h2>
            <div className="space-y-4">
              {inProgressCourses.map((course) => (
                <Link
                  key={course.id}
                  to={`/courses/${course.id}`}
                  className="block border rounded-lg p-4 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex justify-between items-center mb-2">
                    <h3 className="font-medium">{course.title}</h3>
                    <span className="text-sm text-gray-500">{course.progress}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2">
                    <div
                      className="bg-blue-500 h-2 rounded-full"
                      style={{ width: `${course.progress}%` }}
                    ></div>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;