import React, { createContext, useState, useContext, useEffect, ReactNode } from 'react';

// Import API URL from environment
const API_URL = (import.meta as any).env?.VITE_API_URL || 'http://localhost:3001';

// User interface
export interface User {
  id: string;
  name: string;
  email: string;
  bio?: string;
  avatar?: string;
}

// Context interface
interface AuthContextType {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  error: string | null;
  login: () => Promise<void>;
  logout: () => void;
  updateProfile: (data: Partial<User>) => Promise<void>;
  clearError: () => void;
  fetchUserProfile: (token: string) => Promise<boolean>;
}

// Create context with default values
export const AuthContext = createContext<AuthContextType>({
  user: null,
  token: null,
  isLoading: false,
  error: null,
  login: async () => {},
  logout: () => {},
  updateProfile: async () => {},
  clearError: () => {},
  fetchUserProfile: async () => false,
});

// Hook to use auth context
export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(localStorage.getItem('token'));
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Check if user is authenticated on mount and token changes
  useEffect(() => {
    const checkAuth = async () => {
      if (token) {
        try {
          setIsLoading(true);
          console.log('Checking auth with token:', token?.substring(0, 10) + '...');
          
          // Make a real API call to get user profile
          const response = await fetch(`${API_URL}/auth/me`, {
            headers: {
              Authorization: `Bearer ${token}`,
            },
            credentials: 'include' // Include cookies for sessions
          });
          
          if (!response.ok) {
            throw new Error('Failed to get user profile');
          }
          
          const userData = await response.json();
          console.log('User data received:', userData);
          setUser(userData);
        } catch (err) {
          console.error('Auth check failed:', err);
          localStorage.removeItem('token');
          setToken(null);
          setUser(null);
          setError('Session expired. Please log in again.');
        } finally {
          setIsLoading(false);
        }
      }
    };

    checkAuth();
  }, [token]);

  const login = async () => {
    window.location.href = `${API_URL}/auth/google`;
  };

  const logout = () => {
    console.log('Logging out user');
    localStorage.removeItem('token');
    setToken(null);
    setUser(null);
  };

  const updateProfile = async (data: Partial<User>) => {
    if (!user || !token) {
      setError('You must be logged in to update your profile');
      return;
    }
    
    try {
      setIsLoading(true);
      const response = await fetch(`${API_URL}/api/users/profile`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(data),
        credentials: 'include' // Include cookies for sessions
      });
      
      if (!response.ok) {
        throw new Error('Failed to update profile');
      }
      
      const updatedUser = await response.json();
      setUser({ ...user, ...updatedUser });
    } catch (err) {
      console.error('Profile update error:', err);
      setError('Failed to update profile. Please try again.');
      throw err;
    } finally {
      setIsLoading(false);
    }
  };

  const clearError = () => {
    setError(null);
  };

  // Fetch user profile with a specific token
  const fetchUserProfile = async (newToken: string): Promise<boolean> => {
    try {
      setIsLoading(true);
      console.log('Fetching user profile with token:', newToken.substring(0, 10) + '...');
      
      const response = await fetch(`${API_URL}/auth/me`, {
        headers: {
          Authorization: `Bearer ${newToken}`,
        },
        credentials: 'include'
      });
      
      if (!response.ok) {
        throw new Error('Failed to get user profile');
      }
      
      const userData = await response.json();
      console.log('User data received:', userData);
      setUser(userData);
      setToken(newToken);
      return true;
    } catch (err) {
      console.error('Failed to fetch user profile:', err);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const authValue: AuthContextType = {
    user,
    token,
    isLoading,
    error,
    login,
    logout,
    updateProfile,
    clearError,
    fetchUserProfile,
  };

  return <AuthContext.Provider value={authValue}>{children}</AuthContext.Provider>;
};